export function StackIcon({
  stack,
  size = 20,
  className,
}: {
  stack: MarketplaceStack
  size?: number
  className?: string
}) {
  const label = MARKETPLACE_STACK_LABEL[stack]

  if (stack === "nextjs") {
    return <NextjsMark size={size} className={className} />
  }
  if (stack === "react") {
    return <ReactMark size={size} className={className} />
  }
  if (stack === "typescript") {
    return <TypescriptMark size={size} className={className} />
  }
  if (stack === "javascript") {
    return <JavascriptMark size={size} className={className} />
  }
  if (stack === "tailwind") {
    return <TailwindMark size={size} className={className} />
  }
  if (stack === "html") {
    return <HtmlMark size={size} className={className} />
  }
  if (stack === "css") {
    return <CssMark size={size} className={className} />
  }
  if (stack === "sass") {
    return <SassMark size={size} className={className} />
  }
  if (stack === "clerk") {
    return <ClerkMark size={size} className={className} />
  }
  if (stack === "authjs") {
    return <AuthjsMark size={size} className={className} />
  }
  if (stack === "jwt") {
    return <JwtMark size={size} className={className} />
  }
  if (stack === "linkedin") {
    return <LinkedinMark size={size} className={className} />
  }
  if (stack === "github") {
    return <GithubMark size={size} className={className} />
  }
  if (stack === "medium") {
    return <MediumMark size={size} className={className} />
  }
  if (stack === "devto") {
    return <DevtoMark size={size} className={className} />
  }
  if (stack === "nodejs") {
    return <NodejsMark size={size} className={className} />
  }
  if (stack === "d3") {
    return <D3Mark size={size} className={className} />
  }
  if (stack === "threejs") {
    return <ThreejsMark size={size} className={className} />
  }
  if (stack === "reactquery") {
    return <ReactQueryMark size={size} className={className} />
  }
  if (stack === "socketio") {
    return <SocketioMark size={size} className={className} />
  }
  if (stack === "prisma") {
    return <PrismaMark size={size} className={className} />
  }
  if (stack === "drizzle") {
    return <DrizzleMark size={size} className={className} />
  }
  if (stack === "npm") {
    return <NpmMark size={size} className={className} />
  }
  if (stack === "gmail") {
    return <GmailMark size={size} className={className} />
  }

  return (
    <span
      className={cn(
        "inline-flex shrink-0 items-center justify-center rounded-sm bg-muted text-[9px] font-bold tracking-tight text-muted-foreground",
        className
      )}
      style={{ width: size, height: size }}
      aria-hidden
      title={label}
    >
      {STACK_INITIAL[stack]}
    </span>
  )
}

export function StackChip({
  stack,
  className,
}: {
  stack: MarketplaceStack
  className?: string
}) {
  return (
    <span
      className={cn(
        "inline-flex items-center gap-1.5 rounded-md border border-border/60 bg-card px-2 py-1 text-xs font-medium text-foreground",
        className
      )}
    >
      <StackIcon stack={stack} size={16} />
      {MARKETPLACE_STACK_LABEL[stack]}
    </span>
  )
}

export const STACK_ICONS_NEEDED: MarketplaceStack[] = [
  "recharts",
  "stripe",
]
